function tokenize(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean);
}

function phraseWindows(tokens, size = 3) {
  const out = [];
  for (let i = 0; i <= tokens.length - size; i += 1) {
    out.push(tokens.slice(i, i + size).join(' '));
  }
  return out;
}

function normalizeText(post) {
  return `${post.title || ''} ${post.body || ''}`.trim();
}

function buildPhraseMap(posts) {
  const map = new Map();

  for (const post of posts) {
    const text = normalizeText(post);
    const tokens = tokenize(text);
    const phrases = new Set(phraseWindows(tokens, 3));

    for (const phrase of phrases) {
      if (phrase.length < 8) continue;
      if (!map.has(phrase)) map.set(phrase, []);
      map.get(phrase).push(post.id);
    }
  }

  return map;
}

export function detectNarratives(posts) {
  const phraseMap = buildPhraseMap(posts);
  const narratives = [];

  for (const [phrase, ids] of phraseMap.entries()) {
    if (ids.length < 2) continue;
    narratives.push({
      id: `nar-${slug(phrase)}`,
      phrase,
      post_ids: Array.from(new Set(ids)).sort(),
      count: Array.from(new Set(ids)).length
    });
  }

  narratives.sort((a, b) => b.count - a.count || a.phrase.localeCompare(b.phrase));
  return narratives.slice(0, 50);
}

export function detectClusters(posts, analyses) {
  const narratives = detectNarratives(posts);
  const scoreMap = new Map(analyses.map((a) => [a.id, a]));

  return narratives.map((nar, index) => {
    const items = nar.post_ids
      .map((id) => scoreMap.get(id))
      .filter(Boolean);

    const avgSynthetic = avg(items.map((x) => x.score.synthetic_language_likelihood || 0));
    const avgSteering = avg(items.map((x) => x.score.narrative_steering_likelihood || 0));
    const avgCoordination = avg(items.map((x) => x.score.coordination_likelihood || 0));

    return {
      id: `clu-${index + 1}-${slug(nar.phrase).slice(0, 24)}`,
      narrative_id: nar.id,
      phrase: nar.phrase,
      post_ids: nar.post_ids,
      size: nar.count,
      average_synthetic_language_likelihood: round2(avgSynthetic),
      average_narrative_steering_likelihood: round2(avgSteering),
      average_coordination_likelihood: round2(avgCoordination),
      suspicion_rank: round2((avgSteering + avgCoordination + avgSynthetic) / 3)
    };
  }).sort((a, b) => b.suspicion_rank - a.suspicion_rank || b.size - a.size);
}

function avg(values) {
  if (!values.length) return 0;
  return values.reduce((a, b) => a + b, 0) / values.length;
}

function round2(n) {
  return Math.round(n * 100) / 100;
}

function slug(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60);
}

